const tabId = 1148881640;
const content = await browserjs(tabId, () => {
  // Let's get the main content area
  const main = document.querySelector('.contentBox') || document.querySelector('main') || document.body;

  // Let's grab all section headings and text
  const sections = [];
  const headings = main.querySelectorAll('h2, h3');
  headings.forEach(h => {
    let text = '';
    let curr = h.nextElementSibling;
    while (curr && !['H2', 'H3'].includes(curr.tagName)) {
      text += curr.innerText + '\n';
      curr = curr.nextElementSibling;
    }
    sections.push({ heading: h.innerText.trim(), text: text.trim() });
  });
  return sections;
});

