const tabId = 1148881640;
const details = await browserjs(tabId, () => {
  const cd = document.evaluate("//h3[contains(., 'Crohn')]", document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
  const hs = document.evaluate("//h3[contains(., 'Hidradenitis')]", document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;

  function getSectionText(node) {
    if (!node) return "";
    let res = "";
    let curr = node.nextElementSibling;
    while (curr && !['H2', 'H3'].includes(curr.tagName)) {
      res += curr.innerText + "\n";
      curr = curr.nextElementSibling;
    }
    return res;
  }

  return {
    crohn: getSectionText(cd),
    hs: getSectionText(hs)
  };
});
